# Exact match checking (6+ words)
import string

def clean_text_for_matching(text):
    # keep punctuation or strip? standard overlap check looks at exact consecutive word matches ignoring punctuation/case
    text_clean = re.sub(r'[^\w\s]', ' ', text.lower())
    words = text_clean.split()
    return words

orig_words = clean_text_for_matching(original_text)
rewrite_words = clean_text_for_matching(rewrite_text)

# Find exact 6+ word matches
orig_str = " ".join(orig_words)

matches = []
i = 0
while i < len(rewrite_words) - 5:
    phrase_len = 6
    phrase = " ".join(rewrite_words[i:i+phrase_len])
    if phrase in orig_str:
        # extend as much as possible
        while i + phrase_len < len(rewrite_words):
            longer_phrase = " ".join(rewrite_words[i:i+phrase_len+1])
            if longer_phrase in orig_str:
                phrase_len += 1
            else:
                break
        exact_match = " ".join(rewrite_words[i:i+phrase_len])
        matches.append((i, phrase_len, exact_match))
        i += phrase_len
    else:
        i += 1

print(f"Total 6+ consecutive word matches: {len(matches)}")
for idx, (pos, length, phrase) in enumerate(matches, 1):
    print(f"{idx}. [{length} words]: \"{phrase}\"")

